import re
import csv
import io
import xml.etree.ElementTree as ET


def _clean_text(s):
    if s is None:
        return ""
    s = s.replace("\u2003", " ")
    s = s.replace("\u2032", "'")
    s = s.replace("\u2020", "")
    s = re.sub(r"\s+", " ", s)
    return s.strip()


def _get_entry_text(entry):
    text = entry.text or ""
    for child in entry:
        if child.text:
            text += child.text
        if child.tail:
            text += child.tail
    return _clean_text(text)


def _parse_rows(table_elem):
    rows = []
    for row in table_elem.iter("row"):
        cells = []
        for entry in row.findall("entry"):
            cells.append(_get_entry_text(entry))
        rows.append(cells)
    return rows


def _to_nm(value, unit):
    try:
        v = float(value)
    except ValueError:
        return None
    unit = unit.lower()
    if unit in ("nm",):
        return _fmt_num(v)
    if unit in ("um", "\u00b5m", "micron", "microm"):
        return _fmt_num(v * 1000)
    if unit in ("mm",):
        return _fmt_num(v * 1000000)
    return _fmt_num(v)


def _fmt_num(v):
    if v == int(v):
        return str(int(v))
    return str(v)


def _is_compound_id(s):
    if not s:
        return False
    digits = re.sub(r"[^\d]", "", s)
    return 4 <= len(digits) <= 7 and digits == re.sub(r"[^\d]", "", s.strip("*").strip())


def _extract_compound_id(s):
    if not s:
        return None
    # strip ISIS prefix, asterisks, footnote marks (daggers, symbols)
    s2 = re.sub(r"(?i)isis\s*", "", s)
    s2 = re.sub(r"[^\d]", "", s2)
    if 4 <= len(s2) <= 7:
        return s2
    return None


def _is_seq(s):
    if not s:
        return False
    cleaned = s.strip().upper()
    letters = re.sub(r"[^ATGC]", "", cleaned)
    return len(letters) >= 8


def _validate_seq(s):
    if not s or s == "NA":
        return "NA"
    cleaned = s.strip().upper()
    letters = re.sub(r"[^ATGC]", "", cleaned)
    if len(letters) >= 8:
        return cleaned
    return "NA"


def _find_header_and_data(rows):
    """Given rows for a single tgroup/table block, determine header rows and data rows.
    Returns (header_rows_list, data_rows_list, ncols)
    """
    # Determine max number of columns from data-like rows
    non_empty_rows = [r for r in rows if any(c.strip() for c in r)]
    if not non_empty_rows:
        return [], [], 0
    ncols = max(len(r) for r in non_empty_rows)
    return ncols


def _unit_multiplier(unit):
    u = unit.lower().strip()
    if u in ("nm",):
        return 1
    if u in ("um", "\u00b5m"):
        return 1000
    if u in ("mm",):
        return 1000000
    return None


def xml_to_csv(xml_str: str) -> str:
    xml_str = xml_str.replace("&#x2003;", " ")
    xml_str = xml_str.replace("&#x2032;", "'")
    xml_str = xml_str.replace("&#x2020;", "")
    xml_str = xml_str.replace("&#x2021;", "")

    # Try to make it well-formed XML by wrapping
    wrapped = "<root>" + xml_str + "</root>"
    try:
        root = ET.fromstring(wrapped)
    except ET.ParseError:
        # attempt cleanup of stray unclosed tags via regex fallback
        cleaned = re.sub(r"<(?!/?(root|tables|table|tgroup|thead|tbody|row|entry|colspec)\b)[^>]*>", "", xml_str)
        wrapped = "<root>" + cleaned + "</root>"
        try:
            root = ET.fromstring(wrapped)
        except ET.ParseError:
            root = None

    output_rows = []

    if root is None:
        return _emit_csv(output_rows)

    for tables_elem in root.iter("tables"):
        for table_elem in tables_elem.findall("table"):
            _process_table(table_elem, output_rows)

    return _emit_csv(output_rows)


def _process_table(table_elem, output_rows):
    tgroups = table_elem.findall("tgroup")
    all_rows = []
    for tg in tgroups:
        rows = _parse_rows(tg)
        all_rows.extend(rows)

    if not all_rows:
        return

    # Filter out completely empty rows but keep track
    rows = all_rows

    # Determine number of data columns (based on rows containing a compound-id-like first cell)
    data_row_indices = []
    for i, r in enumerate(rows):
        if not r:
            continue
        first = r[0].strip()
        cid = _extract_compound_id(first)
        if cid and len(r) >= 2:
            data_row_indices.append(i)

    if not data_row_indices:
        return

    ncols = max(len(rows[i]) for i in data_row_indices)

    # Identify header rows: rows before the first data row that are non-empty
    first_data_idx = data_row_indices[0]
    header_rows = []
    for i in range(first_data_idx):
        r = rows[i]
        if any(c.strip() for c in r):
            # skip pure title/caption rows (usually single cell, or table label)
            header_rows.append((i, r))

    # Try to build column headers by combining header rows, aligned to the right
    # We align header rows to data columns by assuming they may be right-shifted/missing leading empty cell
    col_headers = [[] for _ in range(ncols)]

    for i, r in header_rows:
        # skip rows that look like pure captions (single non-empty cell with long text and rest empty, and only one row)
        if len(r) == 1 and len(header_rows) > 1:
            continue
        L = len(r)
        if L == ncols:
            offset = 0
        elif L == ncols - 1:
            offset = 1
        elif L < ncols:
            offset = ncols - L
        else:
            offset = 0
        for j, val in enumerate(r):
            col_idx = j + offset
            if col_idx < ncols and val.strip():
                col_headers[col_idx].append(val.strip())

    combined_headers = [" ".join(h).strip() for h in col_headers]
    combined_headers_lower = [h.lower() for h in combined_headers]

    # Identify column roles
    compound_col = 0  # always first column based on data rows
    seq_col = None
    sugar_col = None
    backbone_col = None
    inhibition_col = None
    utc_col = None
    dose_cols = {}  # col_idx -> nM value

    for idx, h in enumerate(combined_headers_lower):
        if "sequence" in h:
            seq_col = idx
        if "motif" in h and "sugar" in h:
            sugar_col = idx
        if "linkage" in h or ("backbone" in h):
            backbone_col = idx
        if "inhibition" in h:
            inhibition_col = idx
        if "utc" in h or "% control" in h or "control)" in h or h.strip() == "control":
            utc_col = idx

    # detect dose columns: header cells with number + unit (uM, nM, mM)
    # search each header row for patterns like "0.11" combined with a unit row nearby
    # We'll try to detect using combined_headers strings that contain digits and unit
    unit_pattern = re.compile(r"([0-9]*\.?[0-9]+)\s*(u|\u00b5|n|m)m\b", re.IGNORECASE)
    for idx, h in enumerate(combined_headers):
        m = unit_pattern.search(h.replace(" ", ""))
        if m:
            val = m.group(1)
            unit_char = m.group(2).lower()
            unit = unit_char + "m"
            mult = _unit_multiplier(unit)
            if mult is not None:
                try:
                    nm_val = float(val) * mult
                    dose_cols[idx] = _fmt_num(nm_val)
                except ValueError:
                    pass

    # If no explicit dose columns found via combined headers, try detecting from separate numeric-only header rows plus unit rows
    if not dose_cols:
        # look for a header row consisting mostly of numbers, and another consisting of units
        num_row = None
        unit_row = None
        for i, r in header_rows:
            non_empty = [c for c in r if c.strip()]
            if not non_empty:
                continue
            if all(re.match(r"^[0-9]*\.?[0-9]+$", c.strip()) for c in non_empty):
                num_row = (i, r)
            elif all(re.match(r"^(u|\u00b5|n|m)m$", c.strip(), re.IGNORECASE) for c in non_empty):
                unit_row = (i, r)
        if num_row and unit_row:
            ni, nr = num_row
            ui, ur = unit_row
            offset_n = ncols - len(nr)
            offset_u = ncols - len(ur)
            for j, val in enumerate(nr):
                col_idx = j + offset_n
                unit_val = None
                uj = col_idx - offset_u
                if 0 <= uj < len(ur):
                    unit_val = ur[uj].strip().lower()
                if unit_val:
                    mult = _unit_multiplier(unit_val)
                    if mult is not None:
                        try:
                            nm_val = float(val) * mult
                            dose_cols[col_idx] = _fmt_num(nm_val)
                        except ValueError:
                            pass

    # Determine sequence column if not found by header but data looks like ATGC seq
    if seq_col is None:
        for i in data_row_indices[:5]:
            r = rows[i]
            for j, val in enumerate(r):
                if j == compound_col:
                    continue
                if _is_seq(val):
                    seq_col = j
                    break
            if seq_col is not None:
                break

    # Determine inhibition col if not identified and no dose cols and no utc col
    if inhibition_col is None and utc_col is None and not dose_cols:
        # look for a column with numeric percent-like values (not seq, not compound, not sugar/backbone)
        candidate_cols = [j for j in range(ncols) if j not in (compound_col, seq_col, sugar_col, backbone_col)]
        for j in candidate_cols:
            vals = []
            for i in data_row_indices:
                r = rows[i]
                if j < len(r):
                    vals.append(r[j].strip())
            numeric_vals = [v for v in vals if re.match(r"^-?[0-9]*\.?[0-9]+$", v)]
            if len(numeric_vals) >= max(1, len(vals) // 2):
                inhibition_col = j
                break

    # Process data rows
    for i in data_row_indices:
        r = rows[i]
        first = r[0].strip()
        cid = _extract_compound_id(first)
        if not cid:
            continue

        seq_val = "NA"
        if seq_col is not None and seq_col < len(r):
            seq_val = _validate_seq(r[seq_col])

        sugar_val = "NA"
        if sugar_col is not None and sugar_col < len(r) and r[sugar_col].strip():
            sugar_val = r[sugar_col].strip()

        backbone_val = "NA"
        if backbone_col is not None and backbone_col < len(r) and r[backbone_col].strip():
            backbone_val = r[backbone_col].strip()

        if dose_cols:
            for col_idx, nm_val in dose_cols.items():
                if col_idx >= len(r):
                    continue
                raw_val = r[col_idx].strip()
                if not raw_val:
                    continue
                m = re.match(r"^-?[0-9]*\.?[0-9]+$", raw_val)
                if not m:
                    continue
                pct_note = "inhibition"
                pct_val = raw_val
                if utc_col is not None:
                    try:
                        pct_val = _fmt_num(100 - float(raw_val))
                        pct_note = "converted from %UTC"
                    except ValueError:
                        continue
                output_rows.append([
                    cid, seq_val, sugar_val, backbone_val, nm_val, pct_val, pct_note
                ])
        else:
            pct_val = None
            pct_note = "inhibition"
            if inhibition_col is not None and inhibition_col < len(r):
                raw_val = r[inhibition_col].strip()
                if re.match(r"^-?[0-9]*\.?[0-9]+$", raw_val):
                    pct_val = raw_val
                    pct_note = "inhibition"
            elif utc_col is not None and utc_col < len(r):
                raw_val = r[utc_col].strip()
                if re.match(r"^-?[0-9]*\.?[0-9]+$", raw_val):
                    try:
                        pct_val = _fmt_num(100 - float(raw_val))
                        pct_note = "converted from %UTC"
                    except ValueError:
                        pct_val = None

            if pct_val is None:
                continue

            output_rows.append([
                cid, seq_val, sugar_val, backbone_val, "NA", pct_val, pct_note
            ])


def _emit_csv(rows):
    output = io.StringIO()
    writer = csv.writer(output, delimiter=",", quoting=csv.QUOTE_MINIMAL, lineterminator="\n")
    writer.writerow(["Compound ID", "sequence", "sugar_motif", "backbone_motif", "dosage_nm", "Inhibition_pct", "measurement_note"])

    for row in rows:
        cid = row[0]
        if not re.match(r"^\d{4,7}$", cid):
            continue
        try:
            float(row[5])
        except (ValueError, TypeError):
            continue
        writer.writerow(row)

    return output.getvalue()
